  `author` int(11) DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=latin1;

/*Data for the table `tp_transport_his` */

/*Table structure for table `tp_type` */

DROP TABLE IF EXISTS `tp_type`;

CREATE TABLE `tp_type` (
  `id` int(11) NOT NULL,
  `code` char(10) NOT NULL,
  `description` char(10) DEFAULT NULL,
  `author` int(11) NOT NULL,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

/*Data for the table `tp_type` */

/*Table structure for table `tp_vehicle_group` */

DROP TABLE IF EXISTS `tp_vehicle_group`;

CREATE TABLE `tp_vehicle_group` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `group` varchar(25) NOT NULL,
  `description` varchar(50) DEFAULT NULL,
  `author` bigint(20) DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=latin1;

/*Data for the table `tp_vehicle_group` */

/*Table structure for table `tp_vehicle_log` */

DROP TABLE IF EXISTS `tp_vehicle_log`;

CREATE TABLE `tp_vehicle_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `sanction_order` bigint(20) NOT NULL,
  `cash_memo_no` varchar(50) DEFAULT NULL,
  `initial_reading` decimal(15,2) DEFAULT NULL,
  `final_reading` decimal(15,2) DEFAULT NULL,
  `km_covered` decimal(15,2) DEFAULT NULL,
  `opening_tank_balance` decimal(15,2) DEFAULT NULL,
  `refuelling` decimal(15,2) DEFAULT NULL,
  `total_fuel` decimal(15,2) DEFAULT NULL,
  `milage` decimal(15,2) DEFAULT NULL,
  `fuel_consumed` decimal(15,2) DEFAULT NULL,
  `closing_tank_balance` decimal(15,2) DEFAULT NULL,
  `location` bigint(20) NOT NULL DEFAULT 0 COMMENT 'fcbl locations only',
  `cost_center` bigint(20) NOT NULL DEFAULT 0 COMMENT 'activity',
  `amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `rate` decimal(15,2) DEFAULT NULL,
  `author` int(11) DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=564 DEFAULT CHARSET=latin1;

/*Data for the table `tp_vehicle_log` */

/*Table structure for table `tp_vehicle_parts` */

DROP TABLE IF EXISTS `tp_vehicle_parts`;

CREATE TABLE `tp_vehicle_parts` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `group` int(11) NOT NULL,
  `code` varchar(100) NOT NULL,
  `uom` int(11) DEFAULT NULL COMMENT 'units,litre,kilometer',
  `description` varchar(300) DEFAULT NULL,
  `author` bigint(20) DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=148 DEFAULT CHARSET=latin1;

/*Data for the table `tp_vehicle_parts` */

/*Table structure for table `tp_vehicle_register` */

DROP TABLE IF EXISTS `tp_vehicle_register`;

CREATE TABLE `tp_vehicle_register` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `registered_date` date DEFAULT NULL,
  `license_plate` int(11) DEFAULT NULL,
  `location` int(6) DEFAULT NULL,
  `head` int(6) DEFAULT NULL,
  `subhead` int(6) DEFAULT NULL,
  `status` decimal(10,0) DEFAULT NULL,
  `pol` enum('0','1') DEFAULT NULL COMMENT '1=pol, 0=service',
  `author` int(6) DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=116 DEFAULT CHARSET=utf8;

